type Result<T>=std::result::Result<T,String>;
fn need(ok:bool,error:&str)->Result<()>{if ok{Ok(())}else{Err(error.into())}}
fn millis()->i64{SystemTime::now().duration_since(UNIX_EPOCH).expect("UTC clock").as_millis()as i64}
fn iso(at:i64)->Result<String>{chrono::DateTime::from_timestamp_millis(at).map(|t|t.to_rfc3339_opts(chrono::SecondsFormat::Millis,true)).ok_or("MEDIAN_CLOCK".into())}
fn hex(s:&str)->bool{s.len()==64&&s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b))}
